# Paste claims: a claim per line of name,amount,date,note for the named person, in order, each added
# (or a matching DRAFT updated) and opened as the open button opens it. One change: every line is
# checked before anything is written, and a refused line or open refuses the whole paste (a bad line
# is a 400, a refused open a 409).
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.paste.ValidatePaste
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: add
# Checks every line, then saves, opens and audits each claim in order, each followed by the figures it moved.
add:
  class: net.officefloor.hq.app.claim.AddPastedClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.paste.RespondWithPaste
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import java.math.BigDecimal;
