                if (now >= terms.maxOpen()) throw MaxOpen.refused(terms);
                if (OpenClaim.opensTo(sheet, claim, people, rates, settings) == ClaimStatus.OPEN) held.put(person.getId(), now + 1);
            }
            persons.add(person);
            built.add(claim);
